script:
await step('Mở Dashboard Tổng quan IoT (/iot/dashboard)', async () => {
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  assert(/\/iot\/dashboard/.test(page.url()), 'Không vào được Dashboard IoT');
  const txt = await page.locator('body').innerText();
  assert(txt.length > 50, 'Nội dung Dashboard IoT trống');
});

await step('Kiểm tra trang Báo cáo Số liệu vận hành IoT (/iot/report/operating)', async () => {
  await page.goto('https://tasks.zuizui.io/iot/report/operating', { waitUntil: 'domcontentloaded' });
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  assert(/\/iot\/report\/operating/.test(page.url()), 'Không mở được Báo cáo Số liệu vận hành IoT');
});

await step('Kiểm tra trang Báo cáo theo khu vực, đơn vị IoT (/iot/report/store)', async () => {
  await page.goto('https://tasks.zuizui.io/iot/report/store', { waitUntil: 'domcontentloaded' });
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  assert(/\/iot\/report\/store/.test(page.url()), 'Không mở được Báo cáo theo đơn vị IoT');
  ctx.log('Đã kiểm tra đầy đủ Dashboard và Báo cáo IoT.');
});
